// cycleFocus fait tourner le focus dans le sens donné, en sautant les éléments
// exclus par minFocus().
func (m *DeleteConfirmModal) cycleFocus(step int) int {
	min := m.minFocus()
	span := 3 - min
	return min + ((m.focused-min+step)%span+span)%span
}

