90			if component.Count > 0 {
91				form.countInput.SetValue(fmt.Sprintf("%d", component.Count))
92			}
93			if component.Nameserver != "" {
94				form.nsInput.SetValue(component.Nameserver)
95			}
96			if component.Type != "" {
97				form.compType = component.Type
98			}
99		}
100	
101		return form
102	}
