126	// handleKeyMsg traite les entrées clavier du formulaire
127	func (f *ComponentForm) handleKeyMsg(msg tea.KeyMsg) (*ComponentForm, tea.Cmd) {
128		switch msg.String() {
129		case "esc":
130			return nil, nil
131		case "down":
132			f.navigateField(1)
133			return f, nil
134		case "up":
135			f.navigateField(-1)
136			return f, nil
137		case "left":
138			if f.focusIndex == 3 {
139				f.cycleType(-1)
140				return f, nil
141			}
142		case "right":
143			if f.focusIndex == 3 {
144				f.cycleType(1)
145				return f, nil
146			}
147		case "enter":
148			return f.handleEnterKey()
149		}
150		return f, f.updateActiveInput(msg)
151	}
