153	// maxFieldIndex returns the maximum field index based on component type
154	func (f *ComponentForm) maxFieldIndex() int {
155		if f.compType == "http" || f.compType == "https" || f.compType == "ssl" {
156			return 4
157		}
158		return 5
159	}
