174	// handleEnterKey traite la touche Enter (submit ou avance au champ suivant)
175	func (f *ComponentForm) handleEnterKey() (*ComponentForm, tea.Cmd) {
176		if f.focusIndex == f.maxFieldIndex() {
177			return f.submitForm()
178		}
179		return f, nil
180	}
