366	// computeGlobalStatus determines overall service health
367	func computeGlobalStatus(components []status.ComponentStatus) shared.ServiceGlobalStatus {
368		if len(components) == 0 {
369			return shared.ServiceStatusUnknown
370		}
371	
372		okCount := 0
373		for _, c := range components {
374			if c.Status == status.StatusOK {
375				okCount++
376			}
377		}
378	
379		if okCount == len(components) {
380			return shared.ServiceStatusAllOK
381		}
382		if okCount == 0 {
383			return shared.ServiceStatusDown
384		}
385		return shared.ServiceStatusDegraded
386	}
