394	func detectDockerImage(name, image string) shared.ToolInfo {
395		tool := shared.ToolInfo{Name: name, Version: image, Source: "image"}
396		cmd := exec.Command("docker", "image", "inspect", "--format", "{{.Id}}", image)
397		if err := cmd.Run(); err == nil {
398			tool.Available = true
399		}
400		return tool
401	}
