403	// detectBinaryTool checks if a binary is available and gets its version
404	func detectBinaryTool(name, binary string, versionArgs ...string) shared.ToolInfo {
405		tool := shared.ToolInfo{Name: name}
406	
407		if _, err := exec.LookPath(binary); err != nil {
408			return tool
409		}
410	
411		tool.Available = true
412		tool.Source = "binary"
413	
414		if len(versionArgs) > 0 {
415			cmd := exec.Command(binary, versionArgs...)
416			if out, err := cmd.Output(); err == nil {
417				tool.Version = cleanVersion(string(out))
418			}
419		}
420	
421		return tool
422	}
