424	// cleanVersion removes whitespace and "docker:" prefix from version strings
425	func cleanVersion(v string) string {
426		v = strings.TrimSpace(v)
427		v = strings.TrimPrefix(v, "docker:")
428		v = strings.TrimSpace(v)
429		// Take first line only
430		if idx := strings.IndexByte(v, '\n'); idx >= 0 {
431			v = v[:idx]
432		}
433		// Clean "git version X.Y.Z" -> "X.Y.Z"
434		v = strings.TrimPrefix(v, "git version ")
435		// Clean "Version: X.Y.Z" -> "X.Y.Z" (Trivy)
436		v = strings.TrimPrefix(v, "Version: ")
437		return v
438	}
