440	// openURL opens a URL in the default browser
441	func openURL(url string) tea.Cmd {
442		return func() tea.Msg {
443			var cmd *exec.Cmd
444			switch runtime.GOOS {
445			case "darwin":
446				cmd = exec.Command("open", url)
447			case "windows":
448				cmd = exec.Command("cmd", "/c", "start", url)
449			default:
450				cmd = exec.Command("xdg-open", url)
451			}
452			_ = cmd.Start()
453			return nil
454		}
455	}
