457	// calculateDiskUsage returns human-readable disk usage for a directory
458	func calculateDiskUsage(dir string) string {
459		cmd := exec.Command("du", "-sh", dir)
460		out, err := cmd.Output()
461		if err != nil {
462			return ""
463		}
464		parts := strings.Fields(string(out))
465		if len(parts) >= 1 {
466			return parts[0]
467		}
468		return ""
469	}
