212			b.WriteString(theme.DimStyle.Render("Docker not available"))
213			return m.renderSection(b.String(), width)
214		}
215	
216		s := m.ociStats
217		b.WriteString(theme.Bg("Images:      ") + renderCountWithSize(s.ImagesCount, s.ImagesSize))
218		b.WriteString("\n")
219		b.WriteString(theme.Bg("Containers:  ") + renderCountWithSize(s.ContainersCount, s.ContainersSize))
220		b.WriteString("\n")
221		b.WriteString(theme.Bg("Volumes:     ") + renderCountWithSize(s.VolumesCount, s.VolumesSize))
222	
223		b.WriteString("\n")
224	
225		return m.renderSection(b.String(), width)
226	}
227	
228	// renderContainersSection renders container counts by state
229	func (m Model) renderContainersSection(width int) string {
230		var b strings.Builder
231	
232		b.WriteString(theme.SubTitleStyle.Render(theme.IconContainer+" Containers") + "\n\n")
233	
234		if m.loadingDocker {
235			b.WriteString(theme.DimStyle.Render("Loading..."))
236			return m.renderSection(b.String(), width)
237		}
238	
239		if m.dockerStats == nil || !m.dockerStats.Available {
240			b.WriteString(theme.DimStyle.Render("Docker not available"))
241			return m.renderSection(b.String(), width)
242		}
243	
244		d := m.dockerStats
245		total := d.Running + d.Stopped + d.Paused
246	
247		b.WriteString(theme.Bg(fmt.Sprintf("%d containers", total)))
248		b.WriteString("\n")
249		b.WriteString(theme.StatusOKStyle.Render(fmt.Sprintf("%s %d running", theme.IconPlay, d.Running)))
250		if d.Stopped > 0 {
251			b.WriteString(theme.Bg("  ") + theme.DimStyle.Render(fmt.Sprintf("%s %d stopped", theme.IconStop, d.Stopped)))
252		}
253		if d.Paused > 0 {
254			b.WriteString(theme.Bg("  ") + theme.StatusWarningStyle.Render(fmt.Sprintf("%s %d paused", theme.IconPause, d.Paused)))
255		}
256	
257		b.WriteString("\n")
258	
259		return m.renderSection(b.String(), width)
260	}
261	
262	// renderToolsSection renders detected DevSecOps tools
263	func (m Model) renderToolsSection(width int) string {
264		var b strings.Builder
265	
266		b.WriteString(theme.SubTitleStyle.Render(theme.IconTools+" Tools") + "\n\n")
267	
268		if m.loadingTools {
269			b.WriteString(theme.DimStyle.Render("Detecting..."))
270			return m.renderSection(b.String(), width)
271		}
272	
273		if len(m.tools) == 0 {
274			b.WriteString(theme.DimStyle.Render("No tools detected"))
275			return m.renderSection(b.String(), width)
276		}
277	
278		// Find max tool name length for alignment
279		maxNameLen := 0
280		for _, tool := range m.tools {
281			if len(tool.Name) > maxNameLen {
282				maxNameLen = len(tool.Name)
283			}
284		}
285	
286		for i, tool := range m.tools {
287			paddedName := tool.Name + strings.Repeat(" ", maxNameLen-len(tool.Name))
288			if tool.Available {
289				b.WriteString(theme.StatusOKStyle.Render("✓") + theme.Bg(" "+paddedName))
290			} else {
291				b.WriteString(theme.DimStyle.Render("✗ " + paddedName))
292			}
293			if i < len(m.tools)-1 {
294				b.WriteString("\n")
295			}
296		}
297	
298		return m.renderSection(b.String(), width)
299	}
300	
301	// renderSection wraps content in a styled section with background
302	func (m Model) renderSection(content string, width int) string {
303		return lipgloss.NewStyle().
304			Background(theme.ColorBackground).
305			Padding(0, 1).
306			Width(width).
307			Render(content)
308	}
309	
310	// columnWidth returns width for each column
311	func (m Model) columnWidth() int {
312		w := (m.width - 6) / 2
313		if w < 30 {
314			w = 30
315		}
316		return w
317	}
318	
319	// filterComponents returns service components filtered by SSL type
320	func (m Model) filterComponents(sslOnly bool) []status.ComponentStatus {
321		var result []status.ComponentStatus
322		for _, c := range m.serviceComponents {
323			isSSL := c.Type == status.TypeSSL
324			if sslOnly == isSSL {
325				result = append(result, c)
326			}
327		}
328		return result
329	}
330	
331	// countStatuses returns OK, Down, Error counts
332	func countStatuses(components []status.ComponentStatus) (ok, down, errCount int) {
333		for _, c := range components {
334			switch c.Status {
335			case status.StatusOK:
336				ok++
337			case status.StatusDown:
338				down++
339			default:
340				errCount++
341			}
342		}
343		return
344	}
345	
346	// renderCount formats a count with highlight if > 0
347	func renderCount(n int) string {
348		if n > 0 {
349			return theme.PrimaryColorStyle.Bold(true).Render(fmt.Sprintf("%d", n))
350		}
351		return theme.DimStyle.Render("0")
352	}
353	
354	// renderCountWithSize formats "N (size)" with styling
355	func renderCountWithSize(count int, size string) string {
356		countStr := renderCount(count)
357		if size != "" {
358			return countStr + theme.DimStyle.Render(fmt.Sprintf("  (%s)", size))
359		}
360		return countStr
361	}
362	
363	// HeaderView interface
364	
365	// GetFooterHeight returns the footer height for this view (Rule 124).
366	func (m Model) GetFooterHeight() int {
367		return 2 // empty line + info line
368	}
369

369	
370	// RenderFooter returns the footer content rendered below the viewport (Rule 124).
371	func (m Model) RenderFooter(width int) string {
372		return theme.EmptyLineBg(width) + "\n" + theme.EmptyLineBg(width)
373	}
374	
375	// GetShortcuts returns the keyboard shortcuts for the header
376	func (m Model) GetShortcuts() shortcut.Shortcuts {
377		shortcuts := []shortcut.Shortcut{
378			{Key: "ctrl+r", Description: "Refresh"},
379		}
380		if m.shared.IsAuthenticated {
381			shortcuts = append(shortcuts,
382				shortcut.Shortcut{Key: "m", Description: "Open MRs"},
383				shortcut.Shortcut{Key: "i", Description: "Open issues"},
384			)
385		}
386		shortcuts = append(shortcuts,
387			shortcut.Shortcut{Key: ":", Description: "Command"},
388			shortcut.Shortcut{Key: "?", Description: "Help"},
389		)
390		return shortcuts
391	}
392	
393	// GetTitle returns the view title
394	func (m Model) GetTitle() string {
395		return theme.IconDashboard + " Dashboard"
396	}
397	
398	// GetIcon returns the view icon
399	func (m Model) GetIcon() string {
400		return ""
401	}
402	
403	// GetHeaderInfo returns the key-value info for the header
404	func (m Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
405		return []shortcut.HeaderInfo{
406			{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
407		}
408	}
409	
410	// GetHelpContent returns help content for the dashboard (Rule 114)
411	func (m Model) GetHelpContent() help.Content {
412		return help.Content{
413			Title:       "Dashboard",
414			Description: "The dashboard provides an overview of all your DevSecOps resources in a two-column layout. Left column shows GitLab activity, service health, SSL certificates, and workspaces. Right column shows OCI resources, container states, and available tools.",
415			KeyBindings: []help.KeyBinding{
416				{Key: "ctrl+r", Description: "Refresh all dashboard data"},
417				{Key: "m", Description: "Open assigned merge requests in browser (requires authentication)"},
